import { readFileSync } from 'node:fs';
import { describe, expect, it } from 'vitest';
import { encodeObservation, FEATURE_VERSION, type Observation, type SensorConfig } from '../sim';
import { observationToReal } from './units';

interface GoldenCase {
  name: string;
  scale: number;
  sensors: SensorConfig;
  observation: Observation;
  real?: Observation;
  features: number[];
}

// Generated by `npm run sim:golden`; car programs in other languages test their encoders against it.
const golden = JSON.parse(readFileSync(new URL(`../../autonomy/tests/golden/encoder-v${FEATURE_VERSION}.json`, import.meta.url), 'utf8')) as {
  featureVersion: number;
  cases: GoldenCase[];
};

describe('encoder golden file', () => {
  it('belongs to the current feature version', () => {
    expect(golden.featureVersion).toBe(FEATURE_VERSION);
    expect(golden.cases.length).toBeGreaterThan(10);
  });

  // An encoder change without a FEATURE_VERSION bump and a regenerated golden file fails here.
  it.each(golden.cases.map((c) => [c.name, c] as const))('still encodes %s to the same features', (_, c) => {
    expect(Array.from(encodeObservation(c.observation, c.sensors))).toEqual(c.features);
  });

  it('carries the wire form of every scaled observation', () => {
    const scaled = golden.cases.filter((c) => c.scale !== 1);
    expect(scaled.length).toBeGreaterThan(0);
    for (const c of scaled) expect(JSON.parse(JSON.stringify(observationToReal(c.observation, c.scale)))).toEqual(c.real);
  });
});
